<?php require_once __DIR__.'/includes/functions.php';$notice='';if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$name=clean_input($_POST['name']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$message=clean_input($_POST['message']??'');if($name&&$email&&$message){$q=$pdo->prepare('INSERT INTO contact_messages(name,email,phone,subject,message) VALUES(:name,:email,:phone,:subject,:message)');$q->execute([':name'=>$name,':email'=>$email,':phone'=>clean_input($_POST['phone']??''),':subject'=>clean_input($_POST['subject']??''),':message'=>$message]);$notice='Thanks — your message has been received.';}else $notice='Please complete your name, email and message.';}$pageTitle='Contact Us | '.SITE_NAME;include __DIR__.'/includes/header.php';?><div class="page-header"><div class="container"><h1>Contact Us</h1></div></div><main class="container section-tight"><div class="info-columns"><div class="form-card account-card"><h2>Send a message</h2><?php if($notice):?><div class="alert <?=str_contains($notice,'Thanks')?'alert-success':'alert-error'?>"><?=e($notice)?></div><?php endif?><form method="post"><?=csrf_field()?><div class="form-group"><label>Name</label><input name="name" required></div><div class="form-group"><label>Email</label><input type="email" name="email" required></div><div class="form-group"><label>Phone</label><input name="phone"></div><div class="form-group"><label>Subject</label><input name="subject"></div><div class="form-group"><label>Message</label><textarea name="message" required></textarea></div><button class="btn btn-primary">Send Message</button></form></div><div><h2>We are here to help</h2><p><strong>Phone</strong><br><?=e(get_setting('phone'))?></p><p><strong>Email</strong><br><?=e(get_setting('email'))?></p><p><strong>Address</strong><br><?=e(get_setting('address'))?></p></div></div></main><?php include __DIR__.'/includes/footer.php';?>
